[System.IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne '4d99726bb809a56f2bb974085fba5967cf0522cfafe02aa785d733aeb67b4dea') { throw 'Pacote incorreto. Nada foi aplicado.' }
Expand-Archive -LiteralPath $archive -DestinationPath $temp
$executor = (Get-Process -Id $PID).Path
& $executor -NoProfile -ExecutionPolicy Bypass -File (Join-Path $temp 'Aplicar-Xtream.ps1') -Projeto $Projeto
if ($LASTEXITCODE -ne 0) { throw 'Aplicacao interrompida. Envie a mensagem do instalador.' }
Copy-Item -LiteralPath (Join-Path $temp 'Medir-importacao.ps1') -Destination (Join-Path $Projeto 'Medir-importacao.ps1') -Force
if (-not $NaoCompilar) {
    Push-Location $Projeto
    try {
        & (Join-Path $Projeto 'gradlew.bat') assembleDebug
        if ($LASTEXITCODE -ne 0) { throw 'Compilacao falhou. Envie o erro.' }
        Invoke-Item (Join-Path $Projeto 'app/build/outputs/apk/debug')
    } finally { Pop-Location }
}
Write-Host 'Correcao aplicada. Instale o APK por cima da versao atual e abra o aplicativo.'
Write-Host 'Durante o uso, se desejar comparar uma atualizacao de lista, execute Medir-importacao.ps1 -Serial CODIGO_DO_CELULAR e envie o TXT.'
